import { Field, ProfilePatch } from './types';

const INVALID = 'invalid profile';
const MAX_DISPLAY_NAME = 40;
const MAX_TAGS = 5;
const MAX_TAG_LENGTH = 12;
const ALLOWED_KEYS: ReadonlySet<PropertyKey> = new Set(['displayName', 'tags']);

function invalid(): never {
  throw new Error(INVALID);
}

// Reads an own data property without invoking getters.
function readData(obj: object, key: PropertyKey): unknown {
  const desc = Object.getOwnPropertyDescriptor(obj, key);
  if (desc === undefined || !('value' in desc)) invalid();
  return desc.value;
}

function parseDisplayName(value: unknown): Field<string | null> {
  if (value === null) return { kind: 'set', value: null };
  if (typeof value !== 'string') invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME) invalid();
  return { kind: 'set', value: trimmed };
}

function parseTags(value: unknown): Field<string[]> {
  if (value === null) return { kind: 'set', value: [] };
  if (!Array.isArray(value)) invalid();
  const length = value.length;
  if (length > MAX_TAGS) invalid();
  // Every own key must be an index or 'length'; this rejects holes and extra properties.
  if (Reflect.ownKeys(value).length !== length + 1) invalid();
  const tags: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < length; i++) {
    const item = readData(value, String(i));
    if (typeof item !== 'string') invalid();
    const trimmed = item.trim();
    if (trimmed.length < 1 || trimmed.length > MAX_TAG_LENGTH) invalid();
    if (seen.has(trimmed)) invalid();
    seen.add(trimmed);
    tags.push(trimmed);
  }
  return { kind: 'set', value: tags };
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (!ALLOWED_KEYS.has(key)) invalid();
  }

  let displayName: Field<string | null> = { kind: 'keep' };
  let tags: Field<string[]> = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    displayName = parseDisplayName(readData(input, 'displayName'));
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    tags = parseTags(readData(input, 'tags'));
  }
  return { displayName, tags };
}

